232	    fn split(mut self) -> (Self, Option<Self>) {
233	        // explore while front is of size one.
234	        while self.to_explore.len() == 1 {
235	            let front_node = self.to_explore.pop().unwrap();
236	            self.to_explore.extend((self.children_of)(&front_node));
237	            self.seen.push(front_node);
238	        }
239	        // now take half of the front.
240	        let right_children = split_vec(&mut self.to_explore);
241	        let right = right_children
242	            .map(|c| {
243	                let right_seen = std::mem::take(&mut self.seen); // postfix -> upper nodes are processed last
244	                WalkTreePostfixProducer {
245	                    to_explore: c,
246	                    seen: right_seen,
247	                    children_of: self.children_of,
248	                }
249	            })
250	            .or_else(|| {
251	                // we can still try to divide 'seen'
252	                let right_seen = split_vec(&mut self.seen);
253	                right_seen.map(|mut s| {
254	                    std::mem::swap(&mut self.seen, &mut s);
255	                    WalkTreePostfixProducer {
256	                        to_explore: Default::default(),
257	                        seen: s,
258	                        children_of: self.children_of,
259	                    }
260	                })
261	            });
262	        (self, right)
