265	    fn fold_with<F>(self, mut folder: F) -> F
266	    where
267	        F: Folder<Self::Item>,
268	    {
269	        // now do all remaining explorations
270	        for e in self.to_explore {
271	            folder = consume_rec_postfix(&self.children_of, e, folder);
272	            if folder.full() {
273	                return folder;
274	            }
275	        }
276	        // end by consuming everything seen
277	        folder.consume_iter(self.seen.into_iter().rev())
278	    }
279	}
