281	fn consume_rec_postfix<F, S, B, I>(children_of: &B, s: S, mut folder: F) -> F
282	where
283	    F: Folder<S>,
284	    B: Fn(&S) -> I,
285	    I: IntoIterator<Item = S>,
286	{
287	    let children = (children_of)(&s).into_iter();
288	    for child in children {
289	        folder = consume_rec_postfix(children_of, child, folder);
290	        if folder.full() {
291	            return folder;
292	        }
293	    }
294	    folder.consume(s)
295	}
